examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchStepper(
        steps = steps,
        current = if (domain == null) 0 else 1,
        compact = MonarchStepperCompactMode.Automatic,
    )
    val current = domain
    if (current == null) {
        Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
            MonarchTextField(
                modifier = Modifier.weight(1f),
                value = typed,
                onValueChange = {
                    typed = it
                    error = null
                },
                label = {{field.label}},
                required = true,
                placeholder = {{field.placeholder}},
                helperText = {{field.description}},
                errorText = error,
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Uri),
            )
            MonarchButton(
                modifier = Modifier.padding(top = MonarchTheme.spacing.space6),
                text = {{connect}},
                onClick = {
                    val host = typed.trim().lowercase().removeSuffix(".")
                    // Validate here, then ask the server to connect it; show its error in errorText.
                    if (host.count { it == '.' } < 2) error = "Enter a subdomain, such as help.example.com." else domain = host
                },
                variant = MonarchButtonVariant.Primary,
            )
        }
    } else {
        Row(verticalAlignment = Alignment.CenterVertically) {
            MonarchText(text = current, modifier = Modifier.weight(1f), style = MonarchTextStyle.Heading)
            MonarchButton(
                text = "Remove domain",
                onClick = { removing = true },
                variant = MonarchButtonVariant.Ghost,
                size = MonarchButtonSize.Sm,
            )
        }
        MonarchDomainProgress(host = current, stage = if (found) MonarchDomainStage.Certificate else MonarchDomainStage.Dns)
        MonarchText(text = "Add these records where the DNS for your domain is managed.")
        MonarchDnsRecordTable(
            records = listOf(
                MonarchDnsRecord("CNAME", current, "domains.example.net", MonarchDnsRecordPurpose.Routing, found = found),
                MonarchDnsRecord("TXT", "_verify.$current", "verify=4f7k2m9q", MonarchDnsRecordPurpose.Verification, found = found),
            ),
        )
        MonarchButton(text = if (found) "Check again" else "Verify DNS", onClick = { found = true })
    }
}
val current = domain
if (removing && current != null) {
    MonarchDialog(
        onDismissRequest = { removing = false },
        title = "Remove $current?",
        description = "The domain stops working here. You can connect it again later.",
        actions = {
            MonarchButton(text = "Cancel", onClick = { removing = false }, variant = MonarchButtonVariant.Ghost)
            MonarchButton(
                text = "Remove domain",
                onClick = {
                    domain = null
                    found = false
                    removing = false
                },
                variant = MonarchButtonVariant.Danger,
            )
        },
    )
}

